insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('1f7f6bcb-9eb1-4169-9208-189b392ef6a4', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', null, 'topic'::public.curated_course_node_type, 'Foundations of Anti-Racist and Anti-Oppressive Social Work', 'Students begin by defining anti-racist and anti-oppressive practice as ethical, relational, institutional, and policy work. The goal is to move beyond awareness into accountable practice that can be observed, supervised, evaluated, and improved.', 0),
  ('6b3e9b70-89d0-4e59-b742-4ac0753cd77c', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '1f7f6bcb-9eb1-4169-9208-189b392ef6a4', 'subtopic'::public.curated_course_node_type, 'Core concepts and vocabulary', 'Students establish a shared language for discussing racism, oppression, privilege, power, marginalization, solidarity, liberation, and accountability in professional practice.', 0),
  ('e5f297f3-d8a0-43ba-b260-790c379b25b0', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '6b3e9b70-89d0-4e59-b742-4ac0753cd77c', 'concept'::public.curated_course_node_type, 'Anti-racism, anti-oppression, equity, equality, justice, liberation', null, 0),
  ('bfe46b49-2e81-4438-a16f-d774bcadf18e', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '6b3e9b70-89d0-4e59-b742-4ac0753cd77c', 'concept'::public.curated_course_node_type, 'Prejudice, discrimination, institutional oppression, structural oppression', null, 1),
  ('20ed49c5-a93b-4cc5-adc4-0028b93b202d', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '6b3e9b70-89d0-4e59-b742-4ac0753cd77c', 'concept'::public.curated_course_node_type, 'Power-over, power-with, empowerment, self-determination, and mutual aid', null, 2),
