  ('49274790-44e2-4285-bfab-0db96a1287dd', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '8db6eca1-5fc5-4931-ae26-d5b104c0e3e3', 'concept'::public.curated_course_node_type, 'NASW ethical commitments and professional responsibilities', null, 0),
  ('acfcbd9f-ff96-40fe-b844-fdcd030ec431', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '8db6eca1-5fc5-4931-ae26-d5b104c0e3e3', 'concept'::public.curated_course_node_type, 'CSWE competency expectations for diversity, human rights, and justice', null, 1),
  ('99a0d40c-552a-4e1a-8464-60edb4cd18f1', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '8db6eca1-5fc5-4931-ae26-d5b104c0e3e3', 'concept'::public.curated_course_node_type, 'Service, dignity, integrity, competence, and social justice in practice choices', null, 2),
  ('d85c0d2d-3768-4952-88d9-efea64b144f4', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '1f7f6bcb-9eb1-4169-9208-189b392ef6a4', 'subtopic'::public.curated_course_node_type, 'From awareness to accountable action', 'Students learn that anti-oppressive work requires observable behavior, feedback, repair, evaluation, and willingness to change systems.', 2),
  ('5e628d92-0318-4511-8d8a-aac685f7c5e2', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'd85c0d2d-3768-4952-88d9-efea64b144f4', 'concept'::public.curated_course_node_type, 'Awareness, knowledge, skills, action, and accountability', null, 0),
  ('e648bd19-8e8c-4f84-963f-ac1a1edd2aaa', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'd85c0d2d-3768-4952-88d9-efea64b144f4', 'concept'::public.curated_course_node_type, 'Avoiding performative commitments and checklist thinking', null, 1),
  ('4fd3c926-868b-433f-8b7e-73c50dcece33', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'd85c0d2d-3768-4952-88d9-efea64b144f4', 'concept'::public.curated_course_node_type, 'Reflective learning cycles and evidence of changed practice', null, 2),
  ('bb8998cf-1a8a-447c-92b6-cae31d67aca9', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', null, 'topic'::public.curated_course_node_type, 'Historical and Structural Roots of Oppression', 'This topic gives students the historical grounding needed to understand present-day inequity as produced by institutions, policy, culture, and professional practice histories rather than by isolated prejudice alone.', 1),
  ('4dd4f0d5-090f-47ef-b8f7-baefd9f7dbb7', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'bb8998cf-1a8a-447c-92b6-cae31d67aca9', 'subtopic'::public.curated_course_node_type, 'Race, colonialism, and social welfare history', 'Students study how helping systems have both challenged and reproduced exclusion, control, assimilation, and paternalism.', 0),
  ('34c05ddf-4a14-4e0a-b35f-4d39a7cbb5ca', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '4dd4f0d5-090f-47ef-b8f7-baefd9f7dbb7', 'concept'::public.curated_course_node_type, 'Settler colonialism, slavery, immigration exclusion, and racial capitalism', null, 0),
  ('db43bf25-4879-4fb1-b212-0a7169cd2fca', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '4dd4f0d5-090f-47ef-b8f7-baefd9f7dbb7', 'concept'::public.curated_course_node_type, 'Charity, poor laws, child welfare, eugenics, and institutionalization', null, 1),
  ('868c6150-7f38-460a-81f4-a8db1b356715', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '4dd4f0d5-090f-47ef-b8f7-baefd9f7dbb7', 'concept'::public.curated_course_node_type, 'Mutual aid, freedom movements, community survival, and resistance', null, 2),
  ('2e2da4d3-a3f7-4966-aa54-35d4ed99e040', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'bb8998cf-1a8a-447c-92b6-cae31d67aca9', 'subtopic'::public.curated_course_node_type, 'Policy-produced inequality', 'This subtopic shows how inequity is built through law, budgets, eligibility rules, zoning, policing, health systems, and labor markets.', 1),
  ('3170c5bd-9e17-4a30-8c36-94614d535db7', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '2e2da4d3-a3f7-4966-aa54-35d4ed99e040', 'concept'::public.curated_course_node_type, 'Housing segregation, redlining, wealth gaps, and displacement', null, 0),
  ('7310dba4-37d3-4835-987c-0cf93be7f797', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '2e2da4d3-a3f7-4966-aa54-35d4ed99e040', 'concept'::public.curated_course_node_type, 'Education, employment, health, immigration, and public benefits policy', null, 1),
  ('081175f6-0b74-469e-91d8-2a4e7da92966', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '2e2da4d3-a3f7-4966-aa54-35d4ed99e040', 'concept'::public.curated_course_node_type, 'Criminalization, surveillance, incarceration, and family regulation', null, 2),
  ('3f0ec007-d63b-4f86-8dd8-d417de567200', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'bb8998cf-1a8a-447c-92b6-cae31d67aca9', 'subtopic'::public.curated_course_node_type, 'Professional complicity and professional repair', 'Students examine how professional roles can reproduce harm and how professions can build reparative practices.', 2),
  ('85e8b505-4db8-42dd-aadd-734db1ff77d3', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '3f0ec007-d63b-4f86-8dd8-d417de567200', 'concept'::public.curated_course_node_type, 'Diagnostic bias, risk assessment, mandated reporting, and coercive systems', null, 0),
  ('af1b49c7-05c0-4fcf-9a21-95b5a92cf5fb', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '3f0ec007-d63b-4f86-8dd8-d417de567200', 'concept'::public.curated_course_node_type, 'Cultural erasure, language access barriers, and expert-centered intervention', null, 1),
  ('fe647b32-8f48-4fa2-949c-ce65f683d49d', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '3f0ec007-d63b-4f86-8dd8-d417de567200', 'concept'::public.curated_course_node_type, 'Apology, repair, policy revision, and community accountability', null, 2),
  ('91fd9479-6352-4524-b12a-c662b9dcc5d6', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', null, 'topic'::public.curated_course_node_type, 'Systemic Racism, Institutional Power, and Policy Context', 'Students learn to map racism and oppression across agencies, laws, budgets, eligibility rules, organizational routines, professional discretion, and social welfare systems.', 2),
  ('e0ef5ceb-558f-487d-bbc0-b340491c1de4', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '91fd9479-6352-4524-b12a-c662b9dcc5d6', 'subtopic'::public.curated_course_node_type, 'Systems thinking for oppression analysis', 'Students learn to map how multiple institutions reinforce each other and create cumulative advantage or disadvantage.', 0),
  ('50424422-5a6f-43fe-a979-6d4d509a992f', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'e0ef5ceb-558f-487d-bbc0-b340491c1de4', 'concept'::public.curated_course_node_type, 'Feedback loops, bottlenecks, eligibility pathways, and decision points', null, 0),
  ('d9de6bf1-a211-466b-ab43-1c7552f78097', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'e0ef5ceb-558f-487d-bbc0-b340491c1de4', 'concept'::public.curated_course_node_type, 'Micro, mezzo, macro, and policy levels of analysis', null, 1),
  ('3963989c-7213-4619-9f55-58d270c1c30c', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'e0ef5ceb-558f-487d-bbc0-b340491c1de4', 'concept'::public.curated_course_node_type, 'Root-cause analysis and systems mapping', null, 2),
