  ('1c44e8ff-0891-45a4-8419-242cac8aa70d', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'fd9c1827-9461-4c3e-9835-4f175d6785b6', 'concept'::public.curated_course_node_type, 'Intake, assessment, referral, documentation, waitlists, and service termination', null, 0),
  ('44911f45-3b8e-45f3-ae0f-3c6cf1e885fe', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'fd9c1827-9461-4c3e-9835-4f175d6785b6', 'concept'::public.curated_course_node_type, 'Risk tools, professional judgment, supervision, and gatekeeping', null, 1),
  ('98e5df9e-1d14-40cd-859e-c02bc4c89f84', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'fd9c1827-9461-4c3e-9835-4f175d6785b6', 'concept'::public.curated_course_node_type, 'Language access, disability access, scheduling, transportation, and digital access', null, 2),
  ('ac47553d-3e3d-437f-bf41-5e2f1f82250a', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '91fd9479-6352-4524-b12a-c662b9dcc5d6', 'subtopic'::public.curated_course_node_type, 'Policy context and administrative burden', 'Students learn how policy design shapes who receives support, who is excluded, and who must bear extra labor to access services.', 2),
  ('fe6d4d9a-e964-4b10-88be-0b742e6d9b5c', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'ac47553d-3e3d-437f-bf41-5e2f1f82250a', 'concept'::public.curated_course_node_type, 'Eligibility rules, documentation demands, sanctions, and surveillance', null, 0),
  ('351197ef-66e3-4a0f-a90b-94b66a4e956d', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'ac47553d-3e3d-437f-bf41-5e2f1f82250a', 'concept'::public.curated_course_node_type, 'Administrative burden and unequal access', null, 1),
  ('9910bb61-50c9-478b-b38c-6c32ef4d3f9b', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'ac47553d-3e3d-437f-bf41-5e2f1f82250a', 'concept'::public.curated_course_node_type, 'Advocacy for simpler, more dignified, and more equitable systems', null, 2),
  ('9411229e-d9b5-4d9b-9f1e-a7807ccf49df', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', null, 'topic'::public.curated_course_node_type, 'Intersectionality and Social Location', 'This section builds the analytic habit of seeing how race, class, gender, sexuality, disability, immigration status, religion, language, age, and geography combine in lived experience and service systems.', 3);
