  ('faf4de95-886e-4eb5-b733-eccc09c83eb4', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'fff19342-e708-4824-975f-20440eacde2f', 'subtopic'::public.curated_course_node_type, 'Privilege as structure and social location', 'Students examine privilege as uneven access to safety, credibility, resources, institutional ease, and decision-making power.', 0),
