  ('4374dabf-e411-43e0-865f-c0423b44b345', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'faf4de95-886e-4eb5-b733-eccc09c83eb4', 'concept'::public.curated_course_node_type, 'Resource redistribution, access, and shared power', null, 2),
