  ('82d03085-6eaf-46e4-b284-1c2b5032fae7', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'b8a9ecb6-b2ef-431b-8fc1-1565a528d2c6', 'concept'::public.curated_course_node_type, 'Impact over intent and the ethics of repair', null, 1),
  ('b5ec6384-f22a-458e-9221-fac0ebcee4ad', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'b8a9ecb6-b2ef-431b-8fc1-1565a528d2c6', 'concept'::public.curated_course_node_type, 'Feedback, apology, changed behavior, and sustained accountability', null, 2),
