  ('54922ffc-46a3-41d1-ab79-82452db22f00', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'e1b8939f-2bc7-414c-907b-c7ab0567924e', 'concept'::public.curated_course_node_type, 'Power sharing, access, and accountability', null, 2),
