  ('06435bcd-e7b3-454e-90bc-1977e85598bf', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'ae52e012-57cb-448c-bf63-429d02176652', 'concept'::public.curated_course_node_type, 'Mandated reporting, confidentiality, safety, and surveillance', null, 0),
