  ('88891197-9c35-435e-9832-2468dd5743e6', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'ae52e012-57cb-448c-bf63-429d02176652', 'concept'::public.curated_course_node_type, 'Loyalty to agency, profession, client, community, and law', null, 2),
  ('0189783e-fb5a-4dce-a0c4-cbd53e192fd2', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '3b98d795-ca98-45f8-9cb2-9e53c8406cfc', 'subtopic'::public.curated_course_node_type, 'Decision-making frameworks', 'Students learn structured ways to make and justify ethical decisions in ambiguous, high-stakes practice situations.', 2),
  ('6b30dbf1-51fc-4eab-acbc-8972bd05afa0', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '0189783e-fb5a-4dce-a0c4-cbd53e192fd2', 'concept'::public.curated_course_node_type, 'Ethical consultation, supervision, documentation, and risk analysis', null, 0),
  ('430f1586-ca14-4562-a6c9-a6dd74a1d185', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '0189783e-fb5a-4dce-a0c4-cbd53e192fd2', 'concept'::public.curated_course_node_type, 'Stakeholder mapping and harm-reduction options', null, 1),
  ('89f6f1c9-730c-4bd7-b0dc-e8b359609a9e', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '0189783e-fb5a-4dce-a0c4-cbd53e192fd2', 'concept'::public.curated_course_node_type, 'Least coercive, most empowering, and most accountable alternatives', null, 2),
  ('e9d20748-3a31-4040-8f15-d112f615a521', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', null, 'topic'::public.curated_course_node_type, 'Anti-Oppressive Practice Across Micro, Mezzo, and Macro Levels', 'Students connect direct service, group work, organizational practice, community organizing, and policy advocacy so anti-oppressive practice does not remain confined to interpersonal sensitivity.', 6),
  ('bc3c91f2-6ce1-4e27-8eef-b16f794aa6d2', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'e9d20748-3a31-4040-8f15-d112f615a521', 'subtopic'::public.curated_course_node_type, 'Micro practice with individuals and families', 'Students practice engagement and intervention that respect identity, culture, consent, choice, and structural realities.', 0);
