  ('c74270a5-0382-4b56-84ce-7135efb124c1', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '6b78bc09-1029-4e7e-a29a-ac630b15a185', 'concept'::public.curated_course_node_type, 'Systems change, policy reform, and public accountability', null, 2),
