  ('33f632dd-1a0f-4683-bed7-6332c6ba8561', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'feb00f54-b3c8-4850-900b-f41b13b42a78', 'concept'::public.curated_course_node_type, 'Lifelong learning and critical self-reflection', null, 0),
  ('7fa89ab0-40ac-4037-95e8-503b12742c48', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'feb00f54-b3c8-4850-900b-f41b13b42a78', 'concept'::public.curated_course_node_type, 'Institutional accountability and power imbalance', null, 1),
  ('0b630a11-9390-42bf-882b-124e55e94970', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'feb00f54-b3c8-4850-900b-f41b13b42a78', 'concept'::public.curated_course_node_type, 'Avoiding stereotyping, tokenism, and cultural essentialism', null, 2),
