  ('22ee21d3-9ce5-4e24-adc9-7c17d7a6c8a1', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'e9fa691e-a929-4e4c-8585-bb5ee1634943', 'concept'::public.curated_course_node_type, 'Control, compliance, surveillance, and institutional dependency', null, 2),
  ('46a5bafb-3e11-4ae4-ae8b-260291a6a6a7', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'a2a3faf0-ce50-47ef-b91f-d6573c28adfe', 'subtopic'::public.curated_course_node_type, 'Decolonizing practice commitments', 'This subtopic explores how practice can be guided by community authority, relational accountability, self-determination, and respect for sovereignty.', 1),
  ('7896f8f5-dcd7-4ae8-8b37-764b409869a4', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '46a5bafb-3e11-4ae4-ae8b-260291a6a6a7', 'concept'::public.curated_course_node_type, 'Community-defined needs, priorities, and success', null, 0),
