  ('b4fd9126-172d-49f8-a9b9-5e9545de565f', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '46a5bafb-3e11-4ae4-ae8b-260291a6a6a7', 'concept'::public.curated_course_node_type, 'Consent, reciprocity, non-extraction, and shared ownership', null, 2),
