  ('41300c2e-4960-4e8d-89dd-a64571aba4c8', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', 'd7a02d9e-dc8e-4b84-aa33-495d0cd7fa9f', 'concept'::public.curated_course_node_type, 'Participatory planning, advisory boards, and lived-experience leadership', null, 0),
