  ('4cf34763-a040-47f7-b4dd-771c43d06c20', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '6860e1c7-facc-4bac-8ce6-98d08e8aa143', 'concept'::public.curated_course_node_type, 'Human dignity, participation, non-discrimination, and access', null, 0),
