  ('3678a382-eafe-419d-9f63-bc278fc99e7b', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '6860e1c7-facc-4bac-8ce6-98d08e8aa143', 'concept'::public.curated_course_node_type, 'Local, state, federal, and international rights frameworks', null, 2),
  ('14c87c42-8916-41fc-a589-1cf8e788981b', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '89ca2de5-c24d-4bee-afb5-25220df0ea54', 'subtopic'::public.curated_course_node_type, 'Policy analysis for equity', 'This subtopic teaches students to analyze who benefits, who is burdened, who is excluded, and how policy could be redesigned.', 1),
  ('e2d5cc10-2832-4cfc-8426-ed18037321c8', 'd1e2f3a4-6b7c-4d61-8e01-1f2a3b4c5d11', '14c87c42-8916-41fc-a589-1cf8e788981b', 'concept'::public.curated_course_node_type, 'Problem definition, stakeholders, eligibility, enforcement, and funding', null, 0),
