  'Anti-Racist / Anti-Oppressive Practice prepares students to identify, challenge, and transform oppression in social work relationships, organizations, communities, and policy systems. Students examine racism, colonialism, classism, ableism, heterosexism, sexism, xenophobia, religious oppression, and other intersecting systems of power while developing concrete skills for ethical engagement, assessment, intervention, advocacy, organizational change, and accountability. The course is practice-centered. Students repeatedly move from theory to case analysis, field scenarios, reflective supervision, policy advocacy, organizational diagnosis, and evaluation design. The course treats self-awareness as necessary but insufficient: students must also learn how to redistribute power, change procedures, measure equity outcomes, and remain accountable to clients and communities.',
  $arapjson${"slug": "anti-racist-anti-oppressive-practice", "title": "Anti-Racist / Anti-Oppressive Practice", "description": "Anti-Racist / Anti-Oppressive Practice prepares students to identify, challenge, and transform oppression in social work relationships, organizations, communities, and policy systems. Students examine racism, colonialism, classism, ableism, heterosexism, sexism, xenophobia, religious oppression, and other intersecting systems of power while developing concrete skills for ethical engagement, assessment, intervention, advocacy, organizational change, and accountability. The course is practice-centered. Students repeatedly move from theory to case analysis, field scenarios, reflective supervision, policy advocacy, organizational diagnosis, and evaluation design. The course treats self-awareness as necessary but insufficient: students must also learn how to redistribute power, change procedures, measure equity outcomes, and remain accountable to clients and communities.", "topics": [{"id": "1f7f6bcb-9eb1-4169-9208-189b392ef6a4", "type": "topic", "title": "Foundations of Anti-Racist and Anti-Oppressive Social Work", "description": "Students begin by defining anti-racist and anti-oppressive practice as ethical, relational, institutional, and policy work. The goal is to move beyond awareness into accountable practice that can be observed, supervised, evaluated, and improved.", "children": [{"id": "6b3e9b70-89d0-4e59-b742-4ac0753cd77c", "type": "subtopic", "title": "Core concepts and vocabulary", "children": [{"id": "e5f297f3-d8a0-43ba-b260-790c379b25b0", "type": "concept", "title": "Anti-racism, anti-oppression, equity, equality, justice, liberation"}, {"id": "bfe46b49-2e81-4438-a16f-d774bcadf18e", "type": "concept", "title": "Prejudice, discrimination, institutional oppression, structural oppression"}, {"id": "20ed49c5-a93b-4cc5-adc4-0028b93b202d", "type": "concept", "title": "Power-over, power-with, empowerment, self-determination, and mutual aid"}], "description": "Students establish a shared language for discussing racism, oppression, privilege, power, marginalization, solidarity, liberation, and accountability in professional practice."}, {"id": "8db6eca1-5fc5-4931-ae26-d5b104c0e3e3", "type": "subtopic", "title": "Social work values and professional mandates", "children": [{"id": "49274790-44e2-4285-bfab-0db96a1287dd", "type": "concept", "title": "NASW ethical commitments and professional responsibilities"}, {"id": "acfcbd9f-ff96-40fe-b844-fdcd030ec431", "type": "concept", "title": "CSWE competency expectations for diversity, human rights, and justice"}, {"id": "99a0d40c-552a-4e1a-8464-60edb4cd18f1", "type": "concept", "title": "Service, dignity, integrity, competence, and social justice in practice choices"}], "description": "This subtopic connects anti-oppressive practice to professional ethics rather than treating it as an optional personal preference."}, {"id": "d85c0d2d-3768-4952-88d9-efea64b144f4", "type": "subtopic", "title": "From awareness to accountable action", "children": [{"id": "5e628d92-0318-4511-8d8a-aac685f7c5e2", "type": "concept", "title": "Awareness, knowledge, skills, action, and accountability"}, {"id": "e648bd19-8e8c-4f84-963f-ac1a1edd2aaa", "type": "concept", "title": "Avoiding performative commitments and checklist thinking"}, {"id": "4fd3c926-868b-433f-8b7e-73c50dcece33", "type": "concept", "title": "Reflective learning cycles and evidence of changed practice"}], "description": "Students learn that anti-oppressive work requires observable behavior, feedback, repair, evaluation, and willingness to change systems."}]}, {"id": "bb8998cf-1a8a-447c-92b6-cae31d67aca9", "type": "topic", "title": "Historical and Structural Roots of Oppression", "description": "This topic gives students the historical grounding needed to understand present-day inequity as produced by institutions, policy, culture, and professional practice histories rather than by isolated prejudice alone.", "children": [{"id": "4dd4f0d5-090f-47ef-b8f7-baefd9f7dbb7", "type": "subtopic", "title": "Race, colonialism, and social welfare history", "children": [{"id": "34c05ddf-4a14-4e0a-b35f-4d39a7cbb5ca", "type": "concept", "title": "Settler colonialism, slavery, immigration exclusion, and racial capitalism"}, {"id": "db43bf25-4879-4fb1-b212-0a7169cd2fca", "type": "concept", "title": "Charity, poor laws, child welfare, eugenics, and institutionalization"}, {"id": "868c6150-7f38-460a-81f4-a8db1b356715", "type": "concept", "title": "Mutual aid, freedom movements, community survival, and resistance"}], "description": "Students study how helping systems have both challenged and reproduced exclusion, control, assimilation, and paternalism."}, {"id": "2e2da4d3-a3f7-4966-aa54-35d4ed99e040", "type": "subtopic", "title": "Policy-produced inequality", "children": [{"id": "3170c5bd-9e17-4a30-8c36-94614d535db7", "type": "concept", "title": "Housing segregation, redlining, wealth gaps, and displacement"}, {"id": "7310dba4-37d3-4835-987c-0cf93be7f797", "type": "concept", "title": "Education, employment, health, immigration, and public benefits policy"}, {"id": "081175f6-0b74-469e-91d8-2a4e7da92966", "type": "concept", "title": "Criminalization, surveillance, incarceration, and family regulation"}], "description": "This subtopic shows how inequity is built through law, budgets, eligibility rules, zoning, policing, health systems, and labor markets."}, {"id": "3f0ec007-d63b-4f86-8dd8-d417de567200", "type": "subtopic", "title": "Professional complicity and professional repair", "children": [{"id": "85e8b505-4db8-42dd-aadd-734db1ff77d3", "type": "concept", "title": "Diagnostic bias, risk assessment, mandated reporting, and coercive systems"}, {"id": "af1b49c7-05c0-4fcf-9a21-95b5a92cf5fb", "type": "concept", "title": "Cultural erasure, language access barriers, and expert-centered intervention"}, {"id": "fe647b32-8f48-4fa2-949c-ce65f683d49d", "type": "concept", "title": "Apology, repair, policy revision, and community accountability"}], "description": "Students examine how professional roles can reproduce harm and how professions can build reparative practices."}]}, {"id": "91fd9479-6352-4524-b12a-c662b9dcc5d6", "type": "topic", "title": "Systemic Racism, Institutional Power, and Policy Context", "description": "Students learn to map racism and oppression across agencies, laws, budgets, eligibility rules, organizational routines, professional discretion, and social welfare systems.", "children": [{"id": "e0ef5ceb-558f-487d-bbc0-b340491c1de4", "type": "subtopic", "title": "Systems thinking for oppression analysis", "children": [{"id": "50424422-5a6f-43fe-a979-6d4d509a992f", "type": "concept", "title": "Feedback loops, bottlenecks, eligibility pathways, and decision points"}, {"id": "d9de6bf1-a211-466b-ab43-1c7552f78097", "type": "concept", "title": "Micro, mezzo, macro, and policy levels of analysis"}, {"id": "3963989c-7213-4619-9f55-58d270c1c30c", "type": "concept", "title": "Root-cause analysis and systems mapping"}], "description": "Students learn to map how multiple institutions reinforce each other and create cumulative advantage or disadvantage."}, {"id": "fd9c1827-9461-4c3e-9835-4f175d6785b6", "type": "subtopic", "title": "Institutional routines and discretionary power", "children": [{"id": "1c44e8ff-0891-45a4-8419-242cac8aa70d", "type": "concept", "title": "Intake, assessment, referral, documentation, waitlists, and service termination"}, {"id": "44911f45-3b8e-45f3-ae0f-3c6cf1e885fe", "type": "concept", "title": "Risk tools, professional judgment, supervision, and gatekeeping"}, {"id": "98e5df9e-1d14-40cd-859e-c02bc4c89f84", "type": "concept", "title": "Language access, disability access, scheduling, transportation, and digital access"}], "description": "This subtopic focuses on how ordinary agency procedures can create inequitable outcomes even when explicit bias is denied."}, {"id": "ac47553d-3e3d-437f-bf41-5e2f1f82250a", "type": "subtopic", "title": "Policy context and administrative burden", "children": [{"id": "fe6d4d9a-e964-4b10-88be-0b742e6d9b5c", "type": "concept", "title": "Eligibility rules, documentation demands, sanctions, and surveillance"}, {"id": "351197ef-66e3-4a0f-a90b-94b66a4e956d", "type": "concept", "title": "Administrative burden and unequal access"}, {"id": "9910bb61-50c9-478b-b38c-6c32ef4d3f9b", "type": "concept", "title": "Advocacy for simpler, more dignified, and more equitable systems"}], "description": "Students learn how policy design shapes who receives support, who is excluded, and who must bear extra labor to access services."}]}, {"id": "9411229e-d9b5-4d9b-9f1e-a7807ccf49df", "type": "topic", "title": "Intersectionality and Social Location", "description": "This section builds the analytic habit of seeing how race, class, gender, sexuality, disability, immigration status, religion, language, age, and geography combine in lived experience and service systems.", "children": [{"id": "a001c57b-6aa5-41a3-9b06-2d146ecd4dc4", "type": "subtopic", "title": "Intersectionality as practice analysis", "children": [{"id": "0b6a214c-18c5-4c84-adeb-371093b5bf52", "type": "concept", "title": "Black feminist origins and interlocking systems of power"}, {"id": "8ba46449-289c-4b65-b96c-a1d90e52f4f8", "type": "concept", "title": "Structural, political, and representational intersectionality"}, {"id": "f54f411f-0bc7-4c02-901a-5ddb7100c28a", "type": "concept", "title": "Avoiding single-axis case formulations"}], "description": "Students use intersectionality as a method for understanding power, not as a list of identities."}, {"id": "c3834b15-9c0c-42e7-9847-256b2508d556", "type": "subtopic", "title": "Social location and lived experience", "children": [{"id": "a088024a-a75a-4c5d-8f8e-5fcdd5e3e7ed", "type": "concept", "title": "Race, class, gender, sexuality, disability, immigration, religion, age, and language"}, {"id": "75894ae8-8e1a-418e-bb22-588202dd2dba", "type": "concept", "title": "Rural, urban, tribal, border, carceral, school, health, and housing contexts"}, {"id": "271f1f61-0df0-4ec6-8367-5c0c5cb36cd9", "type": "concept", "title": "Belonging, exclusion, stigma, and resilience"}], "description": "This subtopic helps students understand how identity, history, place, resources, and institutional contact shape service experiences."}, {"id": "cc741927-052f-4cc8-90c4-11432d0f3376", "type": "subtopic", "title": "Intersectional case formulation", "children": [{"id": "fd3c886f-377a-4370-97a4-12fdb10f3f39", "type": "concept", "title": "Strengths, risks, barriers, resources, and power relationships"}, {"id": "ddd49747-48ec-4036-92c1-a4094a34ec27", "type": "concept", "title": "Who defines the problem and who benefits from the definition"}, {"id": "4fe8c1cb-f59e-4f2b-a23f-bf75af4a8794", "type": "concept", "title": "Intervention goals that address both immediate need and structural context"}], "description": "Students practice translating intersectional theory into concrete assessment and intervention choices."}]}, {"id": "fff19342-e708-4824-975f-20440eacde2f", "type": "topic", "title": "Whiteness, Privilege, Fragility, and Accountability", "description": "Students examine privilege as a structural position and practice challenge, with attention to defensiveness, repair, redistribution of power, and accountable professional behavior.", "children": [{"id": "faf4de95-886e-4eb5-b733-eccc09c83eb4", "type": "subtopic", "title": "Privilege as structure and social location", "children": [{"id": "d707abe9-1b17-47be-bdbd-2f4e60b004f5", "type": "concept", "title": "White privilege, class privilege, citizenship, ability, gender, language, and professional status"}, {"id": "91ca659d-fca0-4829-a9a1-907bff5a7dc1", "type": "concept", "title": "Norms, default assumptions, and institutional comfort"}, {"id": "4374dabf-e411-43e0-865f-c0423b44b345", "type": "concept", "title": "Resource redistribution, access, and shared power"}], "description": "Students examine privilege as uneven access to safety, credibility, resources, institutional ease, and decision-making power."}, {"id": "b8a9ecb6-b2ef-431b-8fc1-1565a528d2c6", "type": "subtopic", "title": "Fragility, defensiveness, and repair", "children": [{"id": "bc23e0c1-a24c-4389-bd36-7d69a5b34f05", "type": "concept", "title": "Denial, minimization, exceptionalism, guilt, and centering oneself"}, {"id": "82d03085-6eaf-46e4-b284-1c2b5032fae7", "type": "concept", "title": "Impact over intent and the ethics of repair"}, {"id": "b5ec6384-f22a-458e-9221-fac0ebcee4ad", "type": "concept", "title": "Feedback, apology, changed behavior, and sustained accountability"}], "description": "This subtopic prepares students to notice defensive reactions and move toward accountable learning rather than withdrawal or self-protection."}, {"id": "3ad25b59-532f-406f-849e-4c811718f063", "type": "subtopic", "title": "Accountability practices", "children": [{"id": "ef605b1c-96fc-4d4f-b63f-9a4ba73fc0de", "type": "concept", "title": "Accountability partners, supervision agendas, and reflective questions"}, {"id": "38342027-a695-4b68-a01b-8d88b5317653", "type": "concept", "title": "Transparency about role, limits, power, and choice"}, {"id": "1f7a5c4c-9078-4c8c-a6c0-8220f268a6b6", "type": "concept", "title": "Following community leadership and accepting consequences"}], "description": "Students learn concrete habits that make privilege analysis useful in supervision, teamwork, advocacy, and client relationships."}]}, {"id": "3b98d795-ca98-45f8-9cb2-9e53c8406cfc", "type": "topic", "title": "Anti-Racist Practice Principles and Ethical Commitments", "description": "This topic translates values into practice principles: dignity, self-determination, equity, solidarity, transparency, informed consent, human rights, and professional responsibility.", "children": [{"id": "e1b8939f-2bc7-414c-907b-c7ab0567924e", "type": "subtopic", "title": "Principles for anti-racist practice", "children": [{"id": "6a76f05c-842e-4f3e-9253-7fc19148cc3c", "type": "concept", "title": "Human dignity, self-determination, consent, equity, solidarity, and transparency"}, {"id": "20030c05-992c-4182-b6e0-a46a43dfbd14", "type": "concept", "title": "Strengths-based and rights-based practice"}, {"id": "54922ffc-46a3-41d1-ab79-82452db22f00", "type": "concept", "title": "Power sharing, access, and accountability"}], "description": "Students define guiding principles that can shape engagement, assessment, advocacy, documentation, supervision, and evaluation."}, {"id": "ae52e012-57cb-448c-bf63-429d02176652", "type": "subtopic", "title": "Ethical tensions and practice dilemmas", "children": [{"id": "06435bcd-e7b3-454e-90bc-1977e85598bf", "type": "concept", "title": "Mandated reporting, confidentiality, safety, and surveillance"}, {"id": "0aaa073c-e901-4534-9cd3-54ce578bc481", "type": "concept", "title": "Resource scarcity, eligibility, rationing, and gatekeeping"}, {"id": "88891197-9c35-435e-9832-2468dd5743e6", "type": "concept", "title": "Loyalty to agency, profession, client, community, and law"}], "description": "This subtopic explores moments when professional mandates, agency rules, client priorities, and justice commitments pull in different directions."}, {"id": "0189783e-fb5a-4dce-a0c4-cbd53e192fd2", "type": "subtopic", "title": "Decision-making frameworks", "children": [{"id": "6b30dbf1-51fc-4eab-acbc-8972bd05afa0", "type": "concept", "title": "Ethical consultation, supervision, documentation, and risk analysis"}, {"id": "430f1586-ca14-4562-a6c9-a6dd74a1d185", "type": "concept", "title": "Stakeholder mapping and harm-reduction options"}, {"id": "89f6f1c9-730c-4bd7-b0dc-e8b359609a9e", "type": "concept", "title": "Least coercive, most empowering, and most accountable alternatives"}], "description": "Students learn structured ways to make and justify ethical decisions in ambiguous, high-stakes practice situations."}]}, {"id": "e9d20748-3a31-4040-8f15-d112f615a521", "type": "topic", "title": "Anti-Oppressive Practice Across Micro, Mezzo, and Macro Levels", "description": "Students connect direct service, group work, organizational practice, community organizing, and policy advocacy so anti-oppressive practice does not remain confined to interpersonal sensitivity.", "children": [{"id": "bc3c91f2-6ce1-4e27-8eef-b16f794aa6d2", "type": "subtopic", "title": "Micro practice with individuals and families", "children": [{"id": "befa463f-53b4-4de8-a892-46b2bc6820a1", "type": "concept", "title": "Relationship-building, interviewing, assessment, and goal setting"}, {"id": "68fa74db-2c09-4a9c-86aa-0db79ff59698", "type": "concept", "title": "Documentation and language that protect dignity"}, {"id": "e493197e-9ad2-4222-a315-cc357de87fdb", "type": "concept", "title": "Safety planning, referral, advocacy, and resource navigation"}], "description": "Students practice engagement and intervention that respect identity, culture, consent, choice, and structural realities."}, {"id": "bd695212-7e4d-403f-98ae-dfd6be6911e5", "type": "subtopic", "title": "Mezzo practice with groups and organizations", "children": [{"id": "12f51dff-5b9c-4967-9e69-b72b25c85d82", "type": "concept", "title": "Inclusive group norms and conflict facilitation"}, {"id": "01c2a760-0b2a-4b4e-a524-1815e4d034c2", "type": "concept", "title": "Supervision, staffing, hiring, and professional development"}, {"id": "4ad0988c-d094-4db0-bf60-2be453bba89b", "type": "concept", "title": "Program design, access barriers, and service pathways"}], "description": "This subtopic applies anti-oppressive thinking to group facilitation, teams, supervision, programs, and agency culture."}, {"id": "6b78bc09-1029-4e7e-a29a-ac630b15a185", "type": "subtopic", "title": "Macro practice with communities and systems", "children": [{"id": "b7a5b227-3c38-4b71-bfdb-e5f28199d206", "type": "concept", "title": "Community assessment and participatory planning"}, {"id": "6c1a39c6-fc2a-42af-bf75-5e1a4490dd1d", "type": "concept", "title": "Coalition building, public testimony, and campaign strategy"}, {"id": "c74270a5-0382-4b56-84ce-7135efb124c1", "type": "concept", "title": "Systems change, policy reform, and public accountability"}], "description": "Students learn to connect direct practice to community organizing, policy advocacy, movement work, and institutional reform."}]}, {"id": "c31eb3f1-eefc-4fa9-a523-a517314cdeae", "type": "topic", "title": "Cultural Humility, Reflexivity, and Use of Self", "description": "This section develops the disciplined self-awareness needed for ethical practice: students examine positionality, bias, emotional reactions, power, boundaries, and lifelong learning.", "children": [{"id": "feb00f54-b3c8-4850-900b-f41b13b42a78", "type": "subtopic", "title": "Cultural humility versus competence", "children": [{"id": "33f632dd-1a0f-4683-bed7-6332c6ba8561", "type": "concept", "title": "Lifelong learning and critical self-reflection"}, {"id": "7fa89ab0-40ac-4037-95e8-503b12742c48", "type": "concept", "title": "Institutional accountability and power imbalance"}, {"id": "0b630a11-9390-42bf-882b-124e55e94970", "type": "concept", "title": "Avoiding stereotyping, tokenism, and cultural essentialism"}], "description": "Students learn why humility, curiosity, accountability, and lifelong learning are more defensible than claims of mastering another culture."}, {"id": "afa4b2de-035e-4a6d-98cc-2f55aadec163", "type": "subtopic", "title": "Reflexivity and positionality", "children": [{"id": "66d07b58-0cde-4205-b120-aa7d52ddfbc7", "type": "concept", "title": "Social location, worldview, assumptions, and blind spots"}, {"id": "a9e4ca0f-5f52-461c-96c3-473a4b30c02b", "type": "concept", "title": "Emotional reactions, countertransference-like dynamics, and values conflict"}, {"id": "946e46c7-bf4c-4417-931d-d31281db2e67", "type": "concept", "title": "Reflective journaling, supervision, and peer consultation"}], "description": "This subtopic develops a disciplined practice of examining how the practitioner's identity, role, values, and power affect the helping relationship."}, {"id": "fbef116e-6fe3-4a62-a72b-89745dcaae73", "type": "subtopic", "title": "Professional use of self", "children": [{"id": "00eb13f4-9e9e-4289-a4bb-88cea6033e13", "type": "concept", "title": "Authenticity, boundaries, disclosure, and role clarity"}, {"id": "dc7974f2-9f31-42ac-b050-cdd46c24b4e6", "type": "concept", "title": "Power-aware communication and active listening"}, {"id": "cf9c546e-9437-4830-8707-ae277eac2402", "type": "concept", "title": "Repair after harm and learning from feedback"}], "description": "Students practice using their presence, boundaries, authority, vulnerability, and communication intentionally and ethically."}]}, {"id": "a2a3faf0-ce50-47ef-b91f-d6573c28adfe", "type": "topic", "title": "Power, Decolonizing Practice, and Community Knowledge", "description": "Students learn to recognize colonial, paternalistic, and expert-driven assumptions in helping systems and to build practice that honors community knowledge, sovereignty, and self-determination.", "children": [{"id": "e9fa691e-a929-4e4c-8585-bb5ee1634943", "type": "subtopic", "title": "Coloniality in helping systems", "children": [{"id": "82cfd9cd-918c-4599-89ed-c99e63e6320d", "type": "concept", "title": "Expert-centered practice and deficit narratives"}, {"id": "012a4ba9-7b47-44bb-af4b-f02257832e94", "type": "concept", "title": "Land, sovereignty, family separation, language, and cultural erasure"}, {"id": "22ee21d3-9ce5-4e24-adc9-7c17d7a6c8a1", "type": "concept", "title": "Control, compliance, surveillance, and institutional dependency"}], "description": "Students identify ways that practice can reproduce extraction, surveillance, assimilation, dependency, and professional dominance."}, {"id": "46a5bafb-3e11-4ae4-ae8b-260291a6a6a7", "type": "subtopic", "title": "Decolonizing practice commitments", "children": [{"id": "7896f8f5-dcd7-4ae8-8b37-764b409869a4", "type": "concept", "title": "Community-defined needs, priorities, and success"}, {"id": "cf52cb88-19ee-4cb4-be96-4ae8589e1127", "type": "concept", "title": "Indigenous sovereignty, treaty responsibilities, and local protocol"}, {"id": "b4fd9126-172d-49f8-a9b9-5e9545de565f", "type": "concept", "title": "Consent, reciprocity, non-extraction, and shared ownership"}], "description": "This subtopic explores how practice can be guided by community authority, relational accountability, self-determination, and respect for sovereignty."}, {"id": "d7a02d9e-dc8e-4b84-aa33-495d0cd7fa9f", "type": "subtopic", "title": "Community knowledge and co-production", "children": [{"id": "41300c2e-4960-4e8d-89dd-a64571aba4c8", "type": "concept", "title": "Participatory planning, advisory boards, and lived-experience leadership"}, {"id": "b6fe2f10-94a9-4edc-915a-6906c512f2dc", "type": "concept", "title": "Compensation, credit, and accessible decision-making"}, {"id": "f0916bdc-3283-4930-83e5-5faa8c2c0d43", "type": "concept", "title": "Feedback loops, accountability meetings, and shared evaluation"}], "description": "Students learn to design services, research, and advocacy with community members rather than for them."}]}, {"id": "0bc02662-31ba-4a83-acfe-04100b789f01", "type": "topic", "title": "Microaggressions, Implicit Bias, and Everyday Practice Harms", "description": "This topic helps students identify routine harms that occur in assessment, language, documentation, supervision, team meetings, referrals, and service design.", "children": [{"id": "6ee16aee-b27c-405d-b163-7dd8d2ee3daf", "type": "subtopic", "title": "Implicit bias and professional judgment", "children": [{"id": "7de926f3-451d-451c-8aaa-07ef2d26a0e4", "type": "concept", "title": "Implicit associations and measurement limits"}, {"id": "d86310a4-bfe7-45e2-88c6-4ef34f9ac7cb", "type": "concept", "title": "Bias in assessment, diagnosis, risk tools, and documentation"}, {"id": "01fce3ef-7223-4a47-9328-15ed6ea9232c", "type": "concept", "title": "Debiasing through structure, reflection, feedback, and accountability"}], "description": "Students examine how bias can shape risk perception, credibility judgments, diagnosis, referrals, discipline, and resource allocation."}, {"id": "a3175c10-c708-42e3-b980-4a094b3b000e", "type": "subtopic", "title": "Microaggressions and cumulative harm", "children": [{"id": "e4bb3a65-7947-4c4e-b952-cf5a576d19b5", "type": "concept", "title": "Racial, gendered, ableist, classed, religious, linguistic, and sexuality-based microaggressions"}, {"id": "59c4f9a5-48eb-4fe9-b203-01e7928af487", "type": "concept", "title": "Intent, impact, context, and power"}, {"id": "0dc1ad06-836e-4123-ab5d-4a6b0406d380", "type": "concept", "title": "Cumulative burden, trust erosion, and service disengagement"}], "description": "This subtopic helps students recognize everyday slights, exclusions, assumptions, and invalidations as practice harms with cumulative effects."}, {"id": "e9141c55-4124-4568-a506-714d39f7e6e0", "type": "subtopic", "title": "Repair and prevention", "children": [{"id": "6cc97bf6-75fc-471d-968b-a4dad423d835", "type": "concept", "title": "Naming harm without defensiveness"}, {"id": "ab6da580-c2a6-423a-9b14-7de8e8496652", "type": "concept", "title": "Apology, restitution, changed process, and follow-up"}, {"id": "ec5f67f1-449b-42a6-8405-c3e9771fb372", "type": "concept", "title": "Team norms, supervision, scripts, and documentation practices"}], "description": "Students learn to interrupt harm, apologize effectively, change conditions, and prevent repetition."}]}, {"id": "d04dc20a-2c6a-412c-9d63-5ecc1c71fdb4", "type": "topic", "title": "Trauma-Informed and Healing-Centered Anti-Oppressive Practice", "description": "Students learn to integrate trauma-informed care with structural analysis so practice addresses safety, dignity, cultural context, collective harm, and community healing.", "children": [{"id": "4ce0e171-870f-4162-8895-c4d8f37dbec1", "type": "subtopic", "title": "Trauma, oppression, and historical harm", "children": [{"id": "a491db80-cf29-4611-a38e-fe5df5412dce", "type": "concept", "title": "Historical trauma, racial trauma, migration trauma, and family separation"}, {"id": "4a6e1494-25ac-4c20-b4f5-57bdf1eec7cb", "type": "concept", "title": "Community violence, poverty, exclusion, and state violence"}, {"id": "830c7985-08e1-4647-8e7f-77a0f63fd9e3", "type": "concept", "title": "Pathologizing responses versus understanding survival"}], "description": "Students connect individual trauma to collective, historical, racialized, gendered, colonial, carceral, and institutional harm."}, {"id": "15d42447-3fb1-433c-93e8-e66245e9a892", "type": "subtopic", "title": "Trauma-informed principles", "children": [{"id": "9dc9826e-584c-4f41-9ab5-3a13d4e8dd5d", "type": "concept", "title": "Physical, emotional, cultural, and spiritual safety"}, {"id": "7af787ca-4f91-4a14-b453-804a4628fc7a", "type": "concept", "title": "Transparency, predictability, consent, and choice"}, {"id": "8663f777-eaa1-41ad-a2c2-143cfe95dd8e", "type": "concept", "title": "Collaboration, empowerment, peer support, and identity affirmation"}], "description": "This subtopic teaches students to apply safety, trust, choice, collaboration, and empowerment in culturally responsive ways."}, {"id": "cc38c8aa-71da-4c50-9676-e591c2f4b122", "type": "subtopic", "title": "Healing-centered and community-centered practice", "children": [{"id": "0948dade-37ad-4ef3-bf29-60af405628ab", "type": "concept", "title": "Strengths, belonging, cultural practice, and mutual aid"}, {"id": "ccc02c20-b3de-4d5f-a357-838beb97456c", "type": "concept", "title": "Community healing spaces and peer leadership"}, {"id": "dba30de2-603c-4024-bf31-4fa44304bbf3", "type": "concept", "title": "Avoiding trauma-only narratives and deficit framing"}], "description": "Students explore approaches that emphasize meaning, culture, collective care, joy, resistance, and community capacity."}]}, {"id": "84f85792-6e5a-4a0e-b1c2-d40b44b9d933", "type": "topic", "title": "Assessment, Engagement, and Intervention with Diverse Communities", "description": "This section turns equity commitments into interviewing, assessment, intervention planning, documentation, referral, and evaluation practices with individuals, families, groups, and communities.", "children": [{"id": "81671eea-74fb-4598-9f74-a1c1bbb96d0c", "type": "subtopic", "title": "Equity-centered engagement", "children": [{"id": "cd2805ed-35da-47bf-b254-f91019f226a4", "type": "concept", "title": "Warmth, clarity, informed consent, and role transparency"}, {"id": "76fc7a84-5cde-4241-b6b4-fdb67c3aed62", "type": "concept", "title": "Language access, disability access, and flexible participation"}, {"id": "92b36f21-ccca-4f31-9c12-5298689acc27", "type": "concept", "title": "Respect for naming, pronouns, family structure, culture, and community ties"}], "description": "Students practice first-contact and relationship-building strategies that reduce power imbalance and increase trust."}, {"id": "34e7cfb4-d652-4f9c-8e65-3208e4e54f43", "type": "subtopic", "title": "Anti-oppressive assessment", "children": [{"id": "10be988d-7d47-4ff0-8f6b-41d15755e423", "type": "concept", "title": "Strengths, protective factors, social determinants, and institutional barriers"}, {"id": "2af21f05-4d9f-4ddb-8b07-4fbfa1b3ce53", "type": "concept", "title": "Client-defined goals and culturally meaningful supports"}, {"id": "cd6081a1-9c98-4f8a-9869-8145603c5625", "type": "concept", "title": "Documentation that avoids stereotypes and deficit-only narratives"}], "description": "This subtopic helps students assess needs, strengths, risk, and context without blaming clients for structural barriers."}, {"id": "66061a1b-d4f6-4cae-ac2d-9bd564e24022", "type": "subtopic", "title": "Intervention planning and referral", "children": [{"id": "dff10ba4-55eb-45d5-ad3a-82aceaa94050", "type": "concept", "title": "Safety, stabilization, benefits, housing, health, education, legal, and employment supports"}, {"id": "19b81c56-69a0-441a-88d9-0f74e131e713", "type": "concept", "title": "Warm referrals, accompaniment, and barrier reduction"}, {"id": "98554789-1476-4957-975e-a035dfc4d1ac", "type": "concept", "title": "Client choice, follow-up, and outcome tracking"}], "description": "Students create plans that combine immediate support, advocacy, resource navigation, and systems change."}]}, {"id": "1a23df6b-5b64-4791-9736-82f753e0672c", "type": "topic", "title": "Advocacy, Allyship, Solidarity, and Coalition Practice", "description": "Students distinguish performative allyship from accountable solidarity and learn how advocacy works through relationships, coalitions, community leadership, and shared strategy.", "children": [{"id": "2a60c980-6203-4cfb-903a-77f8e92dd084", "type": "subtopic", "title": "Allyship and solidarity", "children": [{"id": "6bad977d-f61d-44e6-8771-cf74f338ec05", "type": "concept", "title": "Allyship, accompliceship, solidarity, and co-struggle"}, {"id": "b44d2de5-362f-402a-a09c-01477ae60598", "type": "concept", "title": "Listening, taking direction, sharing resources, and accepting critique"}, {"id": "bfc8fa6b-c5fc-4f8a-aaea-12c3b3f8d7e7", "type": "concept", "title": "Avoiding saviorism, centering, and performative action"}], "description": "Students distinguish identity-based intentions from accountable action that follows affected communities and shares risk."}, {"id": "04e2617a-76db-4b6c-a974-31300eb9cb33", "type": "subtopic", "title": "Coalition building", "children": [{"id": "ea474796-aa14-4b80-bc13-dfca70d626af", "type": "concept", "title": "Stakeholder mapping and relationship building"}, {"id": "f8e2e5c9-e203-4372-ae51-74e8dde36a21", "type": "concept", "title": "Shared goals, decision rules, and conflict agreements"}, {"id": "9c1d9dda-0665-483c-a9ee-7f185038c58c", "type": "concept", "title": "Power analysis, trust, repair, and sustainability"}], "description": "This subtopic develops skills for working across difference, tension, power imbalance, and strategic disagreement."}, {"id": "c54519f7-186b-4c33-9e30-a701d5b4b70b", "type": "subtopic", "title": "Advocacy tools", "children": [{"id": "d4621ff9-1094-4766-ad5f-a7b72ca72ab8", "type": "concept", "title": "Letters, testimony, public comment, media advocacy, and briefings"}, {"id": "dff9d5f8-8f89-469f-bbf7-d994c67c68d5", "type": "concept", "title": "Story, data, law, and ethics in persuasive advocacy"}, {"id": "9239f1cd-cfe1-4f9b-96cc-8ae8b5c0cffb", "type": "concept", "title": "Grassroots, grasstops, administrative, and legislative advocacy"}], "description": "Students practice advocacy products and public strategies that social workers use in agencies, communities, and policy spaces."}]}, {"id": "e90b7958-0b7e-45d8-8df4-40a599c2b006", "type": "topic", "title": "Organizational Change and Equity-Centered Leadership", "description": "This topic prepares students to diagnose and change inequitable agency practices, including hiring, supervision, decision-making, data use, policies, climate, accountability, and service access.", "children": [{"id": "610751b5-0829-463d-9b6d-d64510f0db83", "type": "subtopic", "title": "Organizational equity assessment", "children": [{"id": "6383db38-5a76-438c-b8cd-b57453c14c66", "type": "concept", "title": "Equity audits, climate assessments, and policy review"}, {"id": "189c4d71-9f3a-413b-9216-185868736aa7", "type": "concept", "title": "Hiring, promotion, supervision, retention, and compensation"}, {"id": "0187b784-8a1e-429f-8e4e-5cae2f160d96", "type": "concept", "title": "Client access, complaints, outcomes, and service quality"}], "description": "Students learn to evaluate agencies through policies, climate, leadership, service outcomes, access, and staff experience."}, {"id": "fec7edc9-a8f0-40c7-a5ff-3ab48d725a52", "type": "subtopic", "title": "Change strategy and implementation", "children": [{"id": "36faee60-5a86-4f83-abb8-69804441337c", "type": "concept", "title": "Theory of change, implementation plans, and timelines"}, {"id": "5b140476-6903-4036-8a8e-cf12f36f291d", "type": "concept", "title": "Leadership buy-in, staff participation, and community oversight"}, {"id": "0f27feed-2a61-446a-91cf-71fed044f615", "type": "concept", "title": "Budgeting, training, data systems, and public reporting"}], "description": "This subtopic shows how organizational change requires governance, resources, participation, accountability, and sustained leadership."}, {"id": "a2dd343f-98aa-4a83-9ae9-b0611e84bd1b", "type": "subtopic", "title": "Conflict, resistance, and accountability", "children": [{"id": "faea0742-e0aa-44c1-aa47-9e0e39e5b9b4", "type": "concept", "title": "Backlash, fatigue, tokenism, and symbolic compliance"}, {"id": "a7582f1b-a84a-427e-8faa-c0561088aeba", "type": "concept", "title": "Facilitation, conflict transformation, and restorative options"}, {"id": "126d397b-f7b6-44ee-bbfc-dac7b2f43c15", "type": "concept", "title": "Accountability structures, consequences, and follow-through"}], "description": "Students prepare for resistance to equity work and learn how to respond with clarity, boundaries, and process."}]}, {"id": "89ca2de5-c24d-4bee-afb5-25220df0ea54", "type": "topic", "title": "Policy Practice, Human Rights, and Systems Advocacy", "description": "Students connect case-level harms to policy design and learn to create policy briefs, testimony, administrative advocacy, legislative strategy, and rights-based arguments.", "children": [{"id": "6860e1c7-facc-4bac-8ce6-98d08e8aa143", "type": "subtopic", "title": "Rights-based social work", "children": [{"id": "4cf34763-a040-47f7-b4dd-771c43d06c20", "type": "concept", "title": "Human dignity, participation, non-discrimination, and access"}, {"id": "88f269e7-8a35-4342-9ba3-41c7b30a418e", "type": "concept", "title": "Economic, social, cultural, civil, and political rights"}, {"id": "3678a382-eafe-419d-9f63-bc278fc99e7b", "type": "concept", "title": "Local, state, federal, and international rights frameworks"}], "description": "Students connect anti-oppressive practice to human rights, civil rights, social rights, and professional commitments to justice."}, {"id": "14c87c42-8916-41fc-a589-1cf8e788981b", "type": "subtopic", "title": "Policy analysis for equity", "children": [{"id": "e2d5cc10-2832-4cfc-8426-ed18037321c8", "type": "concept", "title": "Problem definition, stakeholders, eligibility, enforcement, and funding"}, {"id": "afbd6f72-487d-4fcb-8a8d-1fdf6afcb100", "type": "concept", "title": "Distributional effects and racial equity impact assessment"}, {"id": "e0f8bd25-d39f-4154-8ba9-d4ca6f309de6", "type": "concept", "title": "Administrative burden, unintended consequences, and implementation gaps"}], "description": "This subtopic teaches students to analyze who benefits, who is burdened, who is excluded, and how policy could be redesigned."}, {"id": "a72b52a1-3466-404f-8177-ed97af0f114d", "type": "subtopic", "title": "Systems advocacy products", "children": [{"id": "2c078741-a101-413f-bf67-0f35be9cb72b", "type": "concept", "title": "Policy briefs, testimony, legislative meetings, and administrative comments"}, {"id": "fb711675-1a25-4c2e-a985-8787c22b8956", "type": "concept", "title": "Coalition platforms and campaign messaging"}, {"id": "f6b96134-aeea-49a0-9724-504f4d907ae4", "type": "concept", "title": "Evaluation of feasibility, ethics, and impact"}], "description": "Students create advocacy materials that are concise, evidence-based, values-grounded, and targeted to decision makers."}]}, {"id": "c411598d-dc89-4a8f-a316-2670a4e11353", "type": "topic", "title": "Research, Program Evaluation, and Accountability for Equity", "description": "This section teaches students to evaluate whether anti-racist and anti-oppressive commitments are producing measurable, meaningful, and community-validated change.", "children": [{"id": "9c04005c-d206-44fa-95c4-f5367a738193", "type": "subtopic", "title": "Evidence and equity questions", "children": [{"id": "c785623a-1e22-425f-9b9c-db31f2de669c", "type": "concept", "title": "Who is reached, excluded, retained, helped, harmed, or over-surveilled"}, {"id": "04dce217-9c04-45dc-8362-04280714d051", "type": "concept", "title": "Outcome, process, access, and experience indicators"}, {"id": "80fe96b6-ef11-4a1e-a61a-fac9c65d4f88", "type": "concept", "title": "Community-defined success and qualitative evidence"}], "description": "Students learn to ask evaluation questions that matter for equity rather than only measuring service volume or satisfaction."}, {"id": "f56fad8b-83d3-43be-aa33-a0950c4b0ee7", "type": "subtopic", "title": "Methods for accountability", "children": [{"id": "58b87e30-d9ef-40a1-b1d6-f874ad2daec0", "type": "concept", "title": "Surveys, interviews, focus groups, case review, observation, and administrative data"}, {"id": "2a3f9d82-ff54-4855-bfce-50a286d3bda8", "type": "concept", "title": "Sampling, measurement, confidentiality, consent, and data quality"}, {"id": "b527a8ef-62a7-4b6f-8b2a-3c0b13dab20c", "type": "concept", "title": "Mixed methods and participatory evaluation"}], "description": "This subtopic connects social work research methods to program improvement and public accountability."}, {"id": "bcf2bfeb-af54-47ba-a67d-f5ac7220e252", "type": "subtopic", "title": "Using data without reproducing harm", "children": [{"id": "58ed793d-b7a9-498e-aa08-a141df28537e", "type": "concept", "title": "Disaggregation, small numbers, privacy, and interpretation limits"}, {"id": "9dd2b1ce-0006-4491-b43a-21989476c2f3", "type": "concept", "title": "Asset-based reporting and context-rich analysis"}, {"id": "6441df0c-4f01-4fc5-a06b-24cb1982544a", "type": "concept", "title": "Data governance, community review, and feedback to participants"}], "description": "Students learn to handle data ethically and to avoid deficit narratives, extraction, and surveillance."}]}, {"id": "abf1912f-18a2-46aa-b905-c5d2f9368bfb", "type": "topic", "title": "Field Practice, Supervision, Ethics, and Reflective Learning", "description": "Students apply the course in field-like scenarios, supervision conversations, ethical dilemmas, documentation exercises, and reflective practice plans.", "children": [{"id": "ee03f820-52bc-4759-aa76-6b1531cb774b", "type": "subtopic", "title": "Field integration", "children": [{"id": "ed80b703-fa03-4cce-9f07-819f4ce14a33", "type": "concept", "title": "Observation of power and access in agency routines"}, {"id": "a733a0df-fa31-41e5-8bdb-f7f1fa1e173f", "type": "concept", "title": "Reflective links between classroom concepts and field events"}, {"id": "3b3f9d93-009c-43d3-a12a-f0b09f16f71a", "type": "concept", "title": "Professional behavior, role clarity, and accountability"}], "description": "Students apply course concepts to field scenarios, agency policies, client interactions, supervision notes, and team decision-making."}, {"id": "e93a6d6b-331a-4362-bbe1-7612b6e55f50", "type": "subtopic", "title": "Equity-centered supervision", "children": [{"id": "45f7f9a7-f9c9-4001-85fa-d6bde7e0c69a", "type": "concept", "title": "Supervision agendas, reflective questions, and feedback requests"}, {"id": "c2c485e2-cde4-4c53-a594-417f13d82570", "type": "concept", "title": "Discussing bias, mistakes, defensiveness, and repair"}, {"id": "552348bc-b6c2-4fa8-aed1-b9aa62ba2e81", "type": "concept", "title": "Supervision documentation and growth planning"}], "description": "This subtopic treats supervision as a site for learning, accountability, ethical reasoning, and institutional change."}, {"id": "64c67d81-39a7-4619-9a83-30acfee3c2c4", "type": "subtopic", "title": "Ethical documentation and professional communication", "children": [{"id": "97c5f6f1-dcd9-4b42-b8ab-791a7ba4ae44", "type": "concept", "title": "Person-first and identity-respecting language"}, {"id": "36259683-1ba4-48ff-a1e4-cd7c2e2e85b3", "type": "concept", "title": "Avoiding coded bias and unsupported judgments"}, {"id": "63373db7-068f-49e3-ab3a-25eb2fc13749", "type": "concept", "title": "Documenting structural barriers, client goals, consent, and advocacy"}], "description": "Students learn how records, emails, case notes, referrals, and team communications can either protect dignity or reproduce harm."}]}, {"id": "b5a41e03-32fd-498e-85b7-14ddd9de7f99", "type": "topic", "title": "Capstone Anti-Oppressive Practice Plan", "description": "The course culminates in a practice plan that synthesizes theory, self-reflection, evidence, community accountability, organizational change, and policy advocacy.", "children": [{"id": "a0039cec-ba0b-4e65-83be-3465fc436929", "type": "subtopic", "title": "Problem and context definition", "children": [{"id": "79d56386-72e7-4817-8bf6-648bd5cba2c8", "type": "concept", "title": "Population, setting, stakeholders, and institutional decision points"}, {"id": "e8099b1c-e743-49c8-af10-a7d843e62d56", "type": "concept", "title": "Evidence of inequity and community-defined concerns"}, {"id": "e63898f1-8c50-4d64-a440-7a361239afaa", "type": "concept", "title": "Scope, constraints, ethics, and assumptions"}], "description": "Students define a practice problem at micro, mezzo, or macro level and situate it in historical, structural, and organizational context."}, {"id": "920a07f9-bf1c-4bce-87ef-e2e5d9a7029a", "type": "subtopic", "title": "Integrated practice strategy", "children": [{"id": "df5801aa-905d-44c5-80ca-9876230a83af", "type": "concept", "title": "Micro, mezzo, and macro actions"}, {"id": "de477331-6add-4425-a60b-6c98d0d9420f", "type": "concept", "title": "Resources, timelines, partners, and accountability structures"}, {"id": "9a71f1fe-fd51-4b43-b9a4-e96fcf8867e2", "type": "concept", "title": "Risk, resistance, harm reduction, and repair planning"}], "description": "This subtopic asks students to synthesize engagement, assessment, intervention, advocacy, organizational change, and evaluation."}, {"id": "5e5c760a-6bb0-4e99-879c-c7c9e6af150c", "type": "subtopic", "title": "Presentation, reflection, and accountability", "children": [{"id": "3f6f94ad-f028-47c4-a030-ba1a99ec8139", "type": "concept", "title": "Capstone presentation and peer feedback"}, {"id": "92135210-21fd-4233-8d8a-5983abbf518e", "type": "concept", "title": "Reflective statement on positionality and use of self"}, {"id": "8f4ef8f7-dea5-4a8d-91b8-3e16574366b7", "type": "concept", "title": "Evaluation plan, sustainability, and future learning commitments"}], "description": "Students complete the course by explaining their plan, receiving critique, revising it, and naming next steps for professional learning."}]}], "dbBacked": true}$arapjson$::jsonb,
